"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["71975"],{27181(e){e.exports=JSON.parse('{"id":"FIN-283","slug":"secondary-market","term":"Secondary Market","also_known_as":[],"difficulty":"Intermediate","definition":"The secondary market is where investors buy and sell securities that have already been issued, trading with each other rather than with the original issuer.","explanation":["Most trading on stock exchanges is secondary market trading. When you buy shares of a listed company through a broker, you are almost always buying them from another investor, not from the company. The company receives no money from that trade.","The secondary market is essential even though issuers do not receive money from it. It provides liquidity: investors know they can sell their securities later if they need cash, which makes them more willing to buy in the first place. It also provides price discovery, as constant trading shows what investors think securities are worth.","For example, a company might sell shares at 20 in its IPO. Over the following years, those shares might trade between investors on the stock exchange at prices from 15 to 60, depending on how the company performs and how investors view its prospects.","The prices set in the secondary market also matter to companies. A higher share price makes it easier and cheaper to raise new money in the primary market and can be used to pay for acquisitions."],"note":"","total":1725,"prev":{"slug":"secondary-buyout","term":"Secondary Buyout"},"next":{"slug":"secondary-offering","term":"Secondary Offering"}}')}}]);